n = int(input())
p = list(map(int, input().split()))

max_happy = 0
for shift in range(n):
    happy_count = 0
    for i in range(n):
        if p[(i + shift) % n] == i or p[(i + shift) % n] == (i - 1) % n or p[(i + shift) % n] == (i + 1) % n:
            happy_count += 1
    max_happy = max(max_happy, happy_count)

print(max_happy)
